"""DER certificate parsing against a certificate generated by openssl.

Skipped when openssl is unavailable; the parser itself never touches the network.
"""
from __future__ import annotations

import shutil
import ssl
import subprocess

import pytest

from websec.net.tls import CertError, parse_certificate


def _certificate(tmp_path) -> str:
    key = tmp_path / "key.pem"
    cert = tmp_path / "cert.pem"
    subprocess.run([
        "openssl", "req", "-x509", "-newkey", "rsa:2048", "-nodes",
        "-keyout", str(key), "-out", str(cert), "-days", "30",
        "-subj", "/CN=example.test/O=Web Sec Lab",
        "-addext", "subjectAltName=DNS:example.test,DNS:www.example.test,IP:203.0.113.10",
    ], check=True, capture_output=True, timeout=60)
    return cert.read_text(encoding="utf-8")


@pytest.mark.skipif(shutil.which("openssl") is None, reason="openssl is not installed")
def test_parse_certificate_reads_names_and_validity(tmp_path):
    der = ssl.PEM_cert_to_DER_cert(_certificate(tmp_path))
    parsed = parse_certificate(der)
    assert parsed["subject"].startswith("CN=example.test")
    assert "example.test" in parsed["sans"]
    assert "www.example.test" in parsed["sans"]
    assert "203.0.113.10" in parsed["sans"]
    assert parsed["not_after"] and parsed["not_before"]
    assert len(parsed["fingerprint_sha256"]) == 64


def test_parse_certificate_refuses_garbage():
    with pytest.raises(CertError):
        parse_certificate(b"\x30\x03\x02\x01")
